head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf35001";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bndMktactTpCd, fileList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf35001.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_40", fn: function(){ return (String((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "tr_41", fn: function(){ return (String((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_when_71_txt", fn: function(){ return ((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'); } }, { id: "c_otherwise_72", fn: function(){ return (!(((dma_pageContext.get("bndMktactTpCd") ?? "") === '113'))); } }, { id: "if_bndGuarTpCd_txt", fn: function(){ return ((dma_result.get("bndGuarTpCd") ?? (() => { throw new Error("unresolved:" + "result.bndGuarTpCd"); })()) !== '4'); } }, { id: "if_coupnRtFinalYn_txt", fn: function(){ return ((dma_result.get("coupnRtFinalYn") ?? (() => { throw new Error("unresolved:" + "result.coupnRtFinalYn"); })()) === 'Y'); } }, { id: "if_coupnRtFinalYn_2_txt", fn: function(){ return ((dma_result.get("coupnRtFinalYn") ?? (() => { throw new Error("unresolved:" + "result.coupnRtFinalYn"); })()) !== 'Y'); } }, { id: "c_when_124", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "tr_125", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "c_otherwise_130", fn: function(){ return (!(((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'))); } }, { id: "c_when_176", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "tr_177", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "if_sfValuYn_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.sfValuYn"); })() === 'Y'); } }, { id: "c_when_247", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() < 5); } }, { id: "c_when_249", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'); } }, { id: "tr_250", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'); } }, { id: "c_otherwise_252", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() < 5) || ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'))); } }, { id: "c_when_242", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_243", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_250", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_253", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "if_nusualBndTpCd", fn: function(){ return ((dma_result.get("nusualBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.nusualBndTpCd"); })()) === '2'); } }, { id: "c_if_350_txt", fn: function(){ return ((((dma_ht.get("basIntList") ?? (() => { throw new Error("unresolved:" + "ht.basIntList"); })())) && typeof ((dma_ht.get("basIntList") ?? (() => { throw new Error("unresolved:" + "ht.basIntList"); })())).getRowCount === 'function' ? ((dma_ht.get("basIntList") ?? (() => { throw new Error("unresolved:" + "ht.basIntList"); })())).getRowCount() : ((((dma_ht.get("basIntList") ?? (() => { throw new Error("unresolved:" + "ht.basIntList"); })())) == null) ? 0 : (((dma_ht.get("basIntList") ?? (() => { throw new Error("unresolved:" + "ht.basIntList"); })())).length || 0))) > 0); } }, { id: "if_intPayMethdCd", fn: function(){ return ((dma_result.get("intPayMethdCd") ?? (() => { throw new Error("unresolved:" + "result.intPayMethdCd"); })()) === '21'); } }, { id: "c_if_443", fn: function(){ return ((((dma_ht.get("callExerList") ?? (() => { throw new Error("unresolved:" + "ht.callExerList"); })())) && typeof ((dma_ht.get("callExerList") ?? (() => { throw new Error("unresolved:" + "ht.callExerList"); })())).getRowCount === 'function' ? ((dma_ht.get("callExerList") ?? (() => { throw new Error("unresolved:" + "ht.callExerList"); })())).getRowCount() : ((((dma_ht.get("callExerList") ?? (() => { throw new Error("unresolved:" + "ht.callExerList"); })())) == null) ? 0 : (((dma_ht.get("callExerList") ?? (() => { throw new Error("unresolved:" + "ht.callExerList"); })())).length || 0))) > 0); } }, { id: "c_if_477", fn: function(){ return ((((dma_ht.get("putExerList") ?? (() => { throw new Error("unresolved:" + "ht.putExerList"); })())) && typeof ((dma_ht.get("putExerList") ?? (() => { throw new Error("unresolved:" + "ht.putExerList"); })())).getRowCount === 'function' ? ((dma_ht.get("putExerList") ?? (() => { throw new Error("unresolved:" + "ht.putExerList"); })())).getRowCount() : ((((dma_ht.get("putExerList") ?? (() => { throw new Error("unresolved:" + "ht.putExerList"); })())) == null) ? 0 : (((dma_ht.get("putExerList") ?? (() => { throw new Error("unresolved:" + "ht.putExerList"); })())).length || 0))) > 0); } }, { id: "c_when_515", fn: function(){ return ((dma_result.get("splitRedmptTpCd") ?? (() => { throw new Error("unresolved:" + "result.splitRedmptTpCd"); })()) === '1' || (dma_result.get("splitRedmptTpCd") ?? (() => { throw new Error("unresolved:" + "result.splitRedmptTpCd"); })()) === '2'); } }, { id: "if_redmptMethdTpCd", fn: function(){ return ((dma_result.get("redmptMethdTpCd") ?? (() => { throw new Error("unresolved:" + "result.redmptMethdTpCd"); })()) === '2'); } }, { id: "c_if_572", fn: function(){ return ((((dma_ht.get("assetList") ?? (() => { throw new Error("unresolved:" + "ht.assetList"); })())) && typeof ((dma_ht.get("assetList") ?? (() => { throw new Error("unresolved:" + "ht.assetList"); })())).getRowCount === 'function' ? ((dma_ht.get("assetList") ?? (() => { throw new Error("unresolved:" + "ht.assetList"); })())).getRowCount() : ((((dma_ht.get("assetList") ?? (() => { throw new Error("unresolved:" + "ht.assetList"); })())) == null) ? 0 : (((dma_ht.get("assetList") ?? (() => { throw new Error("unresolved:" + "ht.assetList"); })())).length || 0))) > 0); } }, { id: "if_apctInnrNo_txt", fn: function(){ return ((dma_result.get("apctInnrNo") ?? (() => { throw new Error("unresolved:" + "result.apctInnrNo"); })()) !== ''); } }, { id: "if_repMajagntComInnrNo_txt", fn: function(){ return ((dma_result.get("repMajagntComInnrNo") ?? (() => { throw new Error("unresolved:" + "result.repMajagntComInnrNo"); })()) !== ''); } }, { id: "c_when_801", fn: function(){ return (!(String(((dma_pageContext.get("fileList") ?? "")) == null ? '' : ((dma_pageContext.get("fileList") ?? ""))).length === 0)); } }, { id: "c_if_822", fn: function(){ return ((((dma_ht.get("princintList") ?? (() => { throw new Error("unresolved:" + "ht.princintList"); })())) && typeof ((dma_ht.get("princintList") ?? (() => { throw new Error("unresolved:" + "ht.princintList"); })())).getRowCount === 'function' ? ((dma_ht.get("princintList") ?? (() => { throw new Error("unresolved:" + "ht.princintList"); })())).getRowCount() : ((((dma_ht.get("princintList") ?? (() => { throw new Error("unresolved:" + "ht.princintList"); })())) == null) ? 0 : (((dma_ht.get("princintList") ?? (() => { throw new Error("unresolved:" + "ht.princintList"); })())).length || 0))) > 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_233", entity: "dlt_htCreditList", countIds: [], cells: [{ childId: "__rc67", fn: function (v, i) { return String(v("creditValuInstNm")); } }, { childId: "__rc68", fn: function (v, i) { return String(v("byinstCreditValuGrd")); } }] },
        { genId: "c_foreach_245", entity: "dlt_htUdwrtInstList", countIds: [], cells: [{ childId: "__rc69", fn: function (v, i) { return String(v("udwrtInstNm")) + " / " + String(v("udwrtAmt")); } }, { childId: "__rc70", fn: function (v, i) { return "기타금액 / " + String(v("udwrtAmt")); } }, { childId: "__rc71", fn: function (v, i) { return String(v("udwrtInstNm")) + " / " + String(v("udwrtAmt")); } }] },
        { genId: "c_foreach_385", entity: "dlt_htIntRtList", countIds: [], cells: [{ childId: "__rc102", fn: function (v, i) { return String(v("intPayDd")); } }, { childId: "__rc103", fn: function (v, i) { return String(v("intRtChgDd")); } }] },
        { genId: "c_foreach_469", entity: "dlt_htCallExerList", countIds: [], cells: [{ childId: "__rc122", fn: function (v, i) { return String(v("callExerStrtDd")); } }, { childId: "__rc123", fn: function (v, i) { return String(v("callExerEndDd")); } }] },
        { genId: "c_foreach_503", entity: "dlt_htPutExerList", countIds: [], cells: [{ childId: "__rc130", fn: function (v, i) { return String(v("putExerStrtDd")); } }, { childId: "__rc131", fn: function (v, i) { return String(v("putExerEndDd")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("bndMktactTpNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return "(" + String(dma_result.get("isurCd")) + ") " + String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb18", fn: function () { return "&nbsp;&nbsp;[보증률(%): " + String(dma_result.get("grtRt")) + " ]"; } },
        { childId: "__rb58", fn: function () { return "시설자금: " + String(dma_result.get("eqmtFnd")); } },
        { childId: "__rb59", fn: function () { return "운영자금: " + String(dma_result.get("operFnd")); } },
        { childId: "__rb60", fn: function () { return "차환자금: " + String(dma_result.get("refundFnd")); } },
        { childId: "__rb61", fn: function () { return "기타자금: " + String(dma_result.get("miscFnd")); } },
        { childId: "__rb79", fn: function () { return String(dma_result.get("cashPayYnNm")) + " " + String(dma_result.get("sbPayYnNm")); } },
        { childId: "__rb88", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnBasIntNm")); } },
        { childId: "__rb90", fn: function () { return String(dma_result.get("spdSgn")) + " " + String(dma_result.get("spd")); } },
        { childId: "__rb99", fn: function () { return String(dma_result.get("intDecsnBasTpNm")) + "로 부터 " + String(dma_result.get("intDecsnBasDys")) + "일전"; } },
        { childId: "__rb104", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnBasIntNm")); } },
        { childId: "__rb105", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtRemainPdNm")); } },
        { childId: "__rb106", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnSpdSgn")) + " " + String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnSpd")); } },
        { childId: "__rb107", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnBasDd")); } },
        { childId: "__rb108", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtDecsnTmNm")); } },
        { childId: "__rb109", fn: function () { return String(dlt_htBasIntList.getCellData(0, "coupnRtMiscBasIntContn")); } },
        { childId: "__rb110", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnBasIntNm")); } },
        { childId: "__rb111", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnRemainPdNm")); } },
        { childId: "__rb112", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnSpdSgn")) + " " + String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnSpd")); } },
        { childId: "__rb113", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnBasDd")); } },
        { childId: "__rb114", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcDecsnTmNm")); } },
        { childId: "__rb115", fn: function () { return String(dlt_htBasIntList.getCellData(0, "isuPrcMiscBasIntContn")); } },
        { childId: "__rb134", fn: function () { return String(dma_result.get("defrMms")) + " 개월"; } },
        { childId: "__rb145", fn: function () { return "내선: " + String(dma_result.get("apctInnrNo")); } },
        { childId: "__rb147", fn: function () { return "내선: " + String(dma_result.get("repMajagntComInnrNo")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldbnf35001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_fileList_oncellclick
 * @description grd_fileList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_fileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_fileList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_fileList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        /* TODO Stage2: 행 동작 미정의: scwin.downloadFile (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_fileList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35001.btn_self_onclick' }); }
};
